<script setup lang="ts">
import AlarmSoundSettings from './AlarmSoundSettings.vue'
import {sortActiveAlarms} from '../alarmNotifications.ts'
import {alarmLimitItems,createAlarmLimits,normalizeAlarmLimits,alarmLimitsError,alarmLimitsSummary,type AlarmLimits} from '../alarmLimits.ts'
import {useDraggablePanel} from '../composables/useDraggablePanel.ts'
import {usePageDraftGuard} from '../composables/usePageDraftGuard.ts'
import { dataTypeLabel } from '../dataTypeLabels.ts'
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { api } from '../api'
import { alarmRuleTypeForDataType, alarmRuleTypeName } from '../alarmRuleType'
import { confirmAction } from '../confirm'
import { useConfigStore } from '../stores/config'

type AlarmRule={ruleId:string;name:string;enabled:boolean;deviceKey:string;metric:string;type:'threshold'|'boolean'|'quality'|'stale';operator?:string;threshold?:number;booleanValue?:boolean;quality?:string;hysteresis:number;triggerDelaySeconds:number;recoveryDelaySeconds:number;level:'INFO'|'WARNING'|'CRITICAL';message?:string;allowManualRecovery?:boolean;popupEnabled?:boolean;soundWhenPopupDisabled?:boolean;retainAfterAcknowledged?:boolean;limits?:AlarmLimits}
type AlarmEvent={eventId:string;ruleId:string;ruleName:string;deviceKey:string;metric:string;pointName?:string;level:string;state:string;acknowledged:boolean;value?:unknown;valueText?:string;threshold?:number;quality?:string;message:string;occurredAt:string;updatedAt:string;recoveredAt?:string;unit?:string;allowManualRecovery?:boolean;recoveryStatus?:string;recoveryHint?:string}
type AlarmSnapshot={active:AlarmEvent[];history:AlarmEvent[];activeCount:number;criticalCount:number;unackedCount:number}
type AlarmHistoryPage={items:AlarmEvent[];page:number;pageSize:number;total:number;totalPages:number}
const props=defineProps<{target?:{deviceKey:string;metric:string;name?:string;nonce:number};centerNonce:number;canManage?:boolean}>()
const {element:dialogElement,style:dialogStyle,start:dragDialog,keyboard:moveDialog}=useDraggablePanel()
const pendingEvent=ref(''),editorError=ref(''),hysteresisHelp=ref(false)
let eventsRequest=0
const canManage=computed(()=>props.canManage===true)
const store=useConfigStore(), tab=ref<'active'|'history'|'rules'|'sound'>('active'), snapshot=ref<AlarmSnapshot>({active:[],history:[],activeCount:0,criticalCount:0,unackedCount:0}), rules=ref<AlarmRule[]>([])
const soundSettings=ref<InstanceType<typeof AlarmSoundSettings>>()
let switchingTab=false
async function selectTab(value:typeof tab.value){
 if(value===tab.value)return true
 if(switchingTab)return false
 switchingTab=true
 try{if(!await requestRulesLeave())return false;if(tab.value==='sound'&&soundSettings.value&&!await soundSettings.value.requestLeave())return false;tab.value=value;return true}
 finally{switchingTab=false}
}
const loading=ref(false), saving=ref(false), historyLoading=ref(false), message=ref(''), editing=ref<AlarmRule>(), timer=ref(0)
const historyPage=ref<AlarmHistoryPage>({items:[],page:1,pageSize:50,total:0,totalPages:0})
const historyFilters=ref({keyword:'',level:'',state:'',startedAt:'',finishedAt:'',pageSize:50})
const savedRulesDraft=ref('')
const initialRuleEditor=ref('')
watch(editing,value=>{initialRuleEditor.value=value?JSON.stringify(value):''},{flush:'sync'})
const ruleEditorDirty=()=>!!editing.value&&JSON.stringify(editing.value)!==initialRuleEditor.value
const requestRulesLeave=usePageDraftGuard(()=>!!savedRulesDraft.value&&(ruleEditorDirty()||JSON.stringify(rules.value)!==savedRulesDraft.value),()=>{editing.value=undefined;rules.value=JSON.parse(savedRulesDraft.value)},async()=>{if(ruleEditorDirty()){applyEdit();if(editing.value)return false}await saveRules()})
const points=computed(()=>{
  const physical=(store.value.devices||[]).flatMap((device:any)=>(device.points||[]).map((point:any)=>({deviceKey:device.deviceKey,deviceName:device.name,metric:point.metric,name:point.name,dataType:point.dataType})))
  const derived=(store.value.edgeComputing?.groups||[]).flatMap((group:any)=>(group.points||[]).map((point:any)=>({deviceKey:group.groupKey,deviceName:group.name,metric:point.metric,name:point.name,dataType:point.dataType})))
  return [...physical,...derived]
})
const editingExisting=computed(()=>!!editing.value&&rules.value.some(item=>item.ruleId===editing.value!.ruleId))
const pointOptions=computed(()=>points.value.map((point:any)=>({...point,key:`${point.deviceKey}::${point.metric}`})))
function pointKey(rule:AlarmRule){return `${rule.deviceKey}::${rule.metric}`}
function selectedPoint(rule:AlarmRule){return pointOptions.value.find((item:any)=>item.deviceKey===rule.deviceKey&&item.metric===rule.metric)}
function selectedDataType(rule:AlarmRule){return selectedPoint(rule)?.dataType||'auto'}
function applyAutomaticRuleType(rule:AlarmRule,point=selectedPoint(rule)){rule.type=alarmRuleTypeForDataType(point?.dataType);syncRuleType(rule)}
function setPoint(rule:AlarmRule,event:Event){const value=(event.target as HTMLSelectElement).value,point=pointOptions.value.find((item:any)=>item.key===value);if(point){rule.deviceKey=point.deviceKey;rule.metric=point.metric;applyAutomaticRuleType(rule,point);if(!rule.name||rule.name.endsWith('告警'))rule.name=`${point.name||point.metric} 告警`}}
function freshRule(target?:{deviceKey:string;metric:string;name?:string}) : AlarmRule {const point=pointOptions.value.find((item:any)=>item.deviceKey===target?.deviceKey&&item.metric===target?.metric)||pointOptions.value[0];const rule:AlarmRule={ruleId:`alarm-${Date.now().toString(36)}`,name:`${target?.name||target?.metric||point?.name||point?.metric||'点位'} 告警`,enabled:true,deviceKey:target?.deviceKey||point?.deviceKey||'',metric:target?.metric||point?.metric||'',type:alarmRuleTypeForDataType(point?.dataType),operator:'>',threshold:0,popupEnabled:true,soundWhenPopupDisabled:false,retainAfterAcknowledged:false,hysteresis:0,triggerDelaySeconds:0,recoveryDelaySeconds:0,level:'WARNING'};syncRuleType(rule);if(rule.type==='threshold')rule.limits=createAlarmLimits();return rule}
async function addRule(target?:{deviceKey:string;metric:string;name?:string}){if(!await selectTab('rules'))return;editorError.value='';editing.value=freshRule(target);tab.value='rules';message.value=''}
function editRule(rule:AlarmRule){const draft:AlarmRule=JSON.parse(JSON.stringify(rule));applyAutomaticRuleType(draft);draft.popupEnabled=draft.popupEnabled!==false;draft.soundWhenPopupDisabled=draft.soundWhenPopupDisabled===true;draft.retainAfterAcknowledged=draft.retainAfterAcknowledged===true;if(draft.limits)draft.limits=normalizeAlarmLimits(draft.limits);editorError.value='';editing.value=draft;tab.value='rules';message.value=''}
function setThresholdMode(event:Event){if(!editing.value)return;editorError.value='';if((event.target as HTMLSelectElement).value==='limits')editing.value.limits=createAlarmLimits();else delete editing.value.limits}
function syncRuleType(rule:AlarmRule){if(rule.type!=='threshold')delete rule.limits;if(rule.type==='threshold'){rule.operator=rule.operator||'>';rule.threshold=rule.threshold??0}else if(rule.type==='boolean')rule.booleanValue=rule.booleanValue??true;else if(rule.type==='quality')rule.quality=rule.quality||'BAD'}
function applyEdit(){if(!editing.value)return;editorError.value=editing.value.limits?alarmLimitsError(editing.value.limits):'';if(editorError.value)return;const index=rules.value.findIndex(item=>item.ruleId===editing.value!.ruleId);if(index>=0)rules.value[index]={...editing.value};else rules.value.push({...editing.value});editing.value=undefined;message.value='规则已加入待保存列表，请点击“保存规则”使其生效'}
async function removeRule(rule:AlarmRule){
  if(!await confirmAction({
    title:'删除告警规则',
    message:`确认删除告警规则“${rule.name}”？`,
    detail:'删除后需点击“保存规则”才会正式生效。',
    confirmText:'确认删除',
    danger:true,
  }))return
  rules.value=rules.value.filter(item=>item.ruleId!==rule.ruleId)
}
async function loadEvents(){const request=++eventsRequest;try{const next=await api<AlarmSnapshot>('/api/alarms?activeOnly=1');if(request===eventsRequest)snapshot.value={...next,active:sortActiveAlarms(next.active)}}catch(error){if(request===eventsRequest)message.value=error instanceof Error?`告警加载失败：${error.message}`:'告警加载失败'}}
async function loadHistory(reset=false){if(reset)historyPage.value.page=1;historyLoading.value=true;try{const params=new URLSearchParams({page:String(historyPage.value.page),pageSize:String(historyFilters.value.pageSize)});for(const key of ['keyword','level','state'] as const){const value=historyFilters.value[key].trim();if(value)params.set(key,value)}if(historyFilters.value.startedAt)params.set('startedAt',new Date(historyFilters.value.startedAt).toISOString());if(historyFilters.value.finishedAt)params.set('finishedAt',new Date(historyFilters.value.finishedAt).toISOString());historyPage.value=await api<AlarmHistoryPage>(`/api/alarms/history?${params}`)}catch(error){message.value=error instanceof Error?`告警历史加载失败：${error.message}`:'告警历史加载失败'}finally{historyLoading.value=false}}
function changeHistoryPage(page:number){if(page<1||page>historyPage.value.totalPages||page===historyPage.value.page)return;historyPage.value.page=page;void loadHistory()}
async function loadRules(){loading.value=true;try{const data=await api<{rules:AlarmRule[]}>('/api/alarm-rules');rules.value=data.rules||[];savedRulesDraft.value=JSON.stringify(rules.value)}catch(error){message.value=error instanceof Error?`告警规则加载失败：${error.message}`:'告警规则加载失败'}finally{loading.value=false}}
async function saveRules(){saving.value=true;message.value='';try{const data=await api<{rules:AlarmRule[]}>('/api/alarm-rules',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({rules:rules.value})});rules.value=data.rules||rules.value;savedRulesDraft.value=JSON.stringify(rules.value);await store.load();await loadEvents();window.dispatchEvent(new Event('gateway-alarms-changed'));message.value='告警规则已保存并热加载，无需重启'}catch(error){message.value=error instanceof Error?error.message:'保存失败'}finally{saving.value=false}}
async function eventAction(event:AlarmEvent,manual=false){if(!canManage.value||pendingEvent.value)return;if(manual&&!event.allowManualRecovery)return;if(manual&&!await confirmAction({title:'手动恢复告警',message:`确认手动恢复“${event.ruleName}”？`,detail:'此操作不代表测量值已正常。同一异常持续期间不重复触发，条件解除后再次异常才重新触发；操作将记录在告警历史中。',confirmText:'手动恢复',danger:true}))return;pendingEvent.value=event.eventId;message.value='';try{await api(`/api/alarms/${manual?'manual-recover':'acknowledge'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({eventId:event.eventId})});message.value=manual?'本次告警已手动恢复，操作记录已保存':'已确认知晓；告警条件解除后才会自动恢复'}catch(error){message.value=error instanceof Error?error.message:'告警操作失败'}finally{pendingEvent.value='';await loadEvents();window.dispatchEvent(new Event('gateway-alarms-changed'))}}
function activeState(event:AlarmEvent){return `${event.recoveryStatus==='recovering'?'等待恢复':event.recoveryStatus==='awaiting_data'?'等待有效数据':'告警中'} · ${event.acknowledged?'已确认':'未确认'}`}
function levelName(value:string){return ({INFO:'提示',WARNING:'警告',CRITICAL:'严重'} as Record<string,string>)[value]||value}
function stateName(value:string){return ({ACTIVE:'告警中',ACKNOWLEDGED:'已确认',RESOLVED:'已恢复',MANUAL_RESOLVED:'手动恢复'} as Record<string,string>)[value]||value}
function ruleCondition(rule:AlarmRule){if(rule.type==='threshold'&&rule.limits)return alarmLimitsSummary(rule.limits);if(rule.type==='threshold')return `${rule.operator} ${rule.threshold}（回差 ${rule.hysteresis||0}）`;if(rule.type==='boolean')return `等于 ${rule.booleanValue}`;if(rule.type==='quality')return `质量为 ${rule.quality}`;return '数据陈旧'}
function formatTime(value?:string){return value?new Date(value).toLocaleString():'-'}
watch(()=>props.target,(target)=>{if(target)addRule(target)},{deep:true})
watch(editing,()=>{hysteresisHelp.value=false})
watch(()=>editing.value?.limits,limits=>{if(editorError.value)editorError.value=limits?alarmLimitsError(limits):''},{deep:true})
watch(()=>props.centerNonce,async()=>{if(await selectTab('active')){editing.value=undefined;message.value=''}})
watch(tab,value=>{if(value==='history'&&!historyPage.value.items.length)void loadHistory(true)})
onMounted(async()=>{await Promise.all([loadEvents(),loadRules()]);timer.value=window.setInterval(loadEvents,2000);if(props.target)addRule(props.target)})
onBeforeUnmount(()=>{eventsRequest++;window.clearInterval(timer.value)})
</script>

<template>
  <section class="alarm-view">
    <header class="alarm-head"><div><h2>告警管理</h2><p>本地实时判定，断网仍可告警；规则保存后立即生效。</p></div><div class="alarm-summary"><span><b>{{snapshot.activeCount}}</b> 当前告警</span><span class="critical"><b>{{snapshot.criticalCount}}</b> 严重</span><span><b>{{snapshot.unackedCount}}</b> 未确认</span></div></header>
    <div class="alarm-toolbar"><div class="alarm-tabs"><button :class="{active:tab==='active'}" @click="selectTab('active')">当前告警 ({{snapshot.activeCount}})</button><button :class="{active:tab==='history'}" @click="selectTab('history')">告警历史</button><button :class="{active:tab==='rules'}" @click="selectTab('rules')">告警规则 ({{rules.length}})</button><button :class="{active:tab==='sound'}" @click="selectTab('sound')">声音设置</button></div><div><button v-if="canManage&&(tab==='rules')" @click="addRule()">新增规则</button><button v-if="canManage&&(tab==='rules')" class="primary" :disabled="saving" @click="saveRules">{{saving?'保存中…':'保存规则'}}</button><button v-else :disabled="historyLoading" @click="tab==='history'?loadHistory():loadEvents()">{{tab==='history'&&historyLoading?'查询中…':'刷新'}}</button></div></div>
    <p v-if="message" class="alarm-message">{{message}}</p>
    <div v-if="tab==='active'" class="alarm-table-wrap"><table><thead><tr><th>等级</th><th>告警名称</th><th>设备 / 点位</th><th>当前值</th><th>质量</th><th>触发时间</th><th>状态</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-if="!snapshot.active.length"><td colspan="9" class="empty">当前没有活动告警</td></tr><tr v-for="event in snapshot.active" :key="event.eventId"><td><span class="level" :class="event.level.toLowerCase()">{{levelName(event.level)}}</span></td><td>{{event.ruleName}}</td><td><b>{{event.pointName||event.metric}}</b><small>{{event.deviceKey}} / {{event.metric}}</small></td><td class="mono">{{event.valueText||(event.value??'-')}} {{event.unit||''}}</td><td>{{event.quality||'-'}}</td><td>{{formatTime(event.occurredAt)}}</td><td><div class="alarm-state-inline"><span>{{activeState(event)}}</span><span v-if="!event.allowManualRecovery" class="alarm-auto-recovery" title="此规则不允许手动恢复；条件解除后自动恢复">仅自动恢复</span></div></td><td>{{event.message}}<small class="alarm-recovery-hint">{{event.recoveryHint||'确认仅表示已知晓；告警条件解除后自动恢复'}}</small></td><td class="alarm-actions-cell"><div class="alarm-actions"><button v-if="canManage" class="alarm-ack-button" :disabled="event.acknowledged||!!pendingEvent" @click="eventAction(event)">{{event.acknowledged?'已确认':'确认知晓'}}</button><button v-if="canManage&&event.allowManualRecovery" class="alarm-recover-button" :disabled="!!pendingEvent" @click="eventAction(event,true)">手动恢复</button></div></td></tr></tbody></table></div>
    <div v-else-if="tab==='history'" class="alarm-history-layout"><div class="alarm-history-filters"><input v-model.trim="historyFilters.keyword" placeholder="搜索规则、设备或点位" @keyup.enter="loadHistory(true)"/><select v-model="historyFilters.level"><option value="">全部等级</option><option value="INFO">提示</option><option value="WARNING">警告</option><option value="CRITICAL">严重</option></select><select v-model="historyFilters.state"><option value="">全部状态</option><option value="ACTIVE">告警触发</option><option value="ACKNOWLEDGED">已确认</option><option value="RESOLVED">已恢复</option><option value="MANUAL_RESOLVED">手动恢复</option></select><label>开始时间<input v-model="historyFilters.startedAt" type="datetime-local"/></label><label>结束时间<input v-model="historyFilters.finishedAt" type="datetime-local"/></label><button class="primary" :disabled="historyLoading" @click="loadHistory(true)">{{historyLoading?'查询中…':'查询'}}</button></div><div class="alarm-table-wrap"><table><thead><tr><th>时间</th><th>事件</th><th>等级</th><th>告警名称</th><th>设备 / 点位</th><th>值</th><th>说明</th></tr></thead><tbody><tr v-if="!historyLoading&&!historyPage.items.length"><td colspan="7" class="empty">暂无告警历史</td></tr><tr v-for="(event,index) in historyPage.items" :key="`${event.eventId}-${event.state}-${index}`"><td>{{formatTime(event.updatedAt)}}</td><td>{{stateName(event.state)}}</td><td><span class="level" :class="event.level.toLowerCase()">{{levelName(event.level)}}</span></td><td>{{event.ruleName}}</td><td>{{event.deviceKey}} / {{event.metric}}</td><td class="mono">{{event.valueText||(event.value??'-')}}</td><td>{{event.message}}</td></tr></tbody></table></div><div class="alarm-history-pagination"><span>共 {{historyPage.total}} 条 · 第 {{historyPage.page}} / {{historyPage.totalPages||1}} 页</span><label>每页<select v-model.number="historyFilters.pageSize" @change="loadHistory(true)"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button :disabled="historyPage.page<=1||historyLoading" @click="changeHistoryPage(historyPage.page-1)">上一页</button><button :disabled="historyPage.page>=historyPage.totalPages||historyLoading" @click="changeHistoryPage(historyPage.page+1)">下一页</button></div></div>
    <AlarmSoundSettings v-else-if="tab==='sound'" ref="soundSettings"/>
    <div v-else class="alarm-rules-layout"><div class="alarm-table-wrap"><table><thead><tr><th>规则名称</th><th>设备 / 点位</th><th>条件</th><th>等级</th><th>触发延时</th><th>恢复延时</th><th>恢复方式</th><th>面板提醒</th><th>操作</th><th class="alarm-rule-enabled">启用</th></tr></thead><tbody><tr v-if="!rules.length"><td colspan="10" class="empty">暂无规则，可从这里新增，也可在点位操作列点击“告警”</td></tr><tr v-for="rule in rules" :key="rule.ruleId" class="alarm-rule-row" :class="{disabled:!rule.enabled}"><td>{{rule.name}}</td><td>{{rule.deviceKey}} / {{rule.metric}}</td><td class="alarm-condition-cell">{{ruleCondition(rule)}}</td><td><span v-if="rule.limits">按限值配置</span><span v-else class="level" :class="rule.level.toLowerCase()">{{levelName(rule.level)}}</span></td><td>{{rule.triggerDelaySeconds||0}} 秒</td><td>{{rule.recoveryDelaySeconds||0}} 秒</td><td>{{rule.allowManualRecovery?'自动 / 手动':'仅自动'}}</td><td>{{rule.popupEnabled===false?(rule.soundWhenPopupDisabled?'关闭 / 仅声音':'关闭'):rule.retainAfterAcknowledged?'保留至恢复':'确认后隐藏'}}</td><td><button v-if="canManage" @click="editRule(rule)">编辑</button><button v-if="canManage" class="danger" @click="removeRule(rule)">删除</button></td><td class="alarm-rule-enabled"><label class="alarm-rule-switch" :title="rule.enabled?'已启用':'已停用'"><input :disabled="!canManage" v-model="rule.enabled" type="checkbox" role="switch" :aria-checked="rule.enabled" :aria-label="`${rule.name}：${rule.enabled?'已启用':'已停用'}`"/><i aria-hidden="true"/></label></td></tr></tbody></table></div></div>
    <div v-if="editing" class="alarm-dialog-backdrop"><div ref="dialogElement" class="alarm-dialog" :style="dialogStyle" role="dialog" aria-modal="true" aria-label="告警规则"><h3 tabindex="0" role="button" title="拖动移动，方向键微调，Home 复位" @pointerdown="dragDialog" @keydown="moveDialog">{{editingExisting?'编辑告警规则':'新增告警规则'}}</h3><div class="alarm-form"><div class="alarm-rule-basics"><label >规则名称<input v-model.trim="editing.name"/></label><label >关联点位<select :value="pointKey(editing)" @change="setPoint(editing,$event)"><option v-for="point in pointOptions" :key="point.key" :value="point.key">{{point.deviceName||point.deviceKey}} / {{point.name||point.metric}}（{{point.metric}}）</option></select></label></div><div class="alarm-rule-columns"><section class="alarm-rule-conditions"><h4>触发条件</h4><div class="alarm-condition-fields"><label>告警类型<div class="alarm-type-display" aria-live="polite"><strong>{{alarmRuleTypeName(editing.type)}}</strong><small>根据 {{dataTypeLabel(selectedDataType(editing))}} 自动判断</small></div></label><template v-if="editing.type==='threshold'"><label>阈值模式<select aria-label="阈值模式" :value="editing.limits?'limits':'single'" @change="setThresholdMode"><option value="limits">四限告警</option><option value="single">单阈值（兼容原规则）</option></select></label><template v-if="!editing.limits"><label>比较条件<select v-model="editing.operator"><option>&gt;</option><option>&gt;=</option><option>&lt;</option><option>&lt;=</option></select></label><label>阈值<input v-model.number="editing.threshold" type="number" step="any"/></label></template><div v-else class="alarm-limits wide"><div class="alarm-limit-head"><span>启用 / 限值</span><span>阈值</span><span>告警等级</span></div><div v-for="item in alarmLimitItems" :key="item.key" class="alarm-limit-row" :class="{disabled:!editing.limits[item.key]?.enabled}"><label><input v-model="editing.limits[item.key]!.enabled" type="checkbox" :aria-label="`启用${item.name}`"/>{{item.name}}</label><label class="alarm-limit-value"><span>{{item.operator}}</span><input v-m