.alarm-table-wrap td .alarm-ack-button{border-color:#bfdbfe;color:#1d4ed8;background:#eff6ff}
.alarm-table-wrap td .alarm-ack-button:hover:not(:disabled){border-color:#60a5fa;color:#1e40af;background:#dbeafe}
.alarm-table-wrap td .alarm-recover-button{border-color:#fed7aa;color:#9a3412;background:#fff7ed}
.alarm-table-wrap td .alarm-recover-button:hover:not(:disabled){border-color:#fb923c;color:#7c2d12;background:#ffedd5}
.alarm-table-wrap td .alarm-ack-button:disabled,.alarm-table-wrap td .alarm-recover-button:disabled{border-color:#e2e8f0;color:#94a3b8;background:#f8fafc;opacity:1}
.alarm-actions button:focus-visible{outline:2px solid #93c5fd;outline-offset:2px}
/* Wide rule editor: all routine fields fit on a desktop without scrolling. */
.alarm-dialog{display:flex;flex-direction:column;width:min(1120px,calc(100vw - 40px));max-height:calc(100dvh - 32px);padding:0;overflow:hidden!important}
.alarm-dialog h3{flex-shrink:0;margin:0;padding:15px 20px;font-size:18px}
.alarm-form{display:block;min-height:0;overflow:auto;padding:64px 20px 16px}
.alarm-rule-basics{display:grid;grid-template-columns:1fr 1.3fr;gap:16px;margin-bottom:16px}
.alarm-rule-columns{display:grid;grid-template-columns:1.12fr 1fr;align-items:start;gap:20px}
.alarm-rule-columns>section{min-width:0}.alarm-rule-columns h4{margin:0 0 12px;font-size:13px;color:#334155}
.alarm-rule-behavior{padding-left:20px;border-left:1px solid #e5edf7}
.alarm-condition-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.alarm-behavior-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.alarm-rule-basics>label,.alarm-condition-fields>label,.alarm-behavior-fields>label{display:flex;min-width:0;flex-direction:column;gap:5px;color:#475569;font-size:12px;font-weight:700}
.alarm-rule-basics input,.alarm-rule-basics select,.alarm-condition-fields>label input,.alarm-condition-fields>label select,.alarm-behavior-fields input{min-width:0;width:100%}
.alarm-form input,.alarm-form select,.alarm-type-display{height:34px}
.alarm-condition-fields .alarm-limits{padding:10px;gap:8px}.alarm-limit-head,.alarm-limit-row{grid-template-columns:90px minmax(80px,1fr) 86px;gap:8px}
.alarm-type-display{gap:5px;padding:0 8px}.alarm-type-display small{font-size:10px}
.alarm-behavior-fields .alarm-form-state{min-height:52px;gap:12px;padding:8px 10px}.alarm-form-state>span{min-width:0}.alarm-form-state small{margin-top:3px;line-height:1.5}.alarm-dialog-switch{flex-shrink:0}
.alarm-reminder-controls{display:flex;align-items:center;justify-content:flex-end;gap:12px;flex-wrap:wrap}.alarm-sound-when-hidden{display:inline-flex;align-items:center;gap:6px;color:#334155;font-size:11px;font-weight:600;white-space:nowrap;cursor:pointer}.alarm-form .alarm-sound-when-hidden input{width:15px;height:15px;margin:0;padding:0;accent-color:#1677ff;cursor:pointer}
.alarm-timing-hysteresis{min-width:0}.alarm-field-heading{height:17px;min-height:17px}
.alarm-rule-behavior .alarm-help-tooltip{top:calc(100% + 8px);bottom:auto;left:-28px}.alarm-rule-behavior .alarm-help-tooltip::after{top:-10px}
.alarm-dialog>.alarm-editor-error{flex-shrink:0;margin:0;padding:8px 20px;background:#fff5f5}
.alarm-dialog>.dialog-actions{flex-shrink:0;margin:0;padding:12px 20px;border-top:1px solid #e5edf7;background:#fbfdff}
/* Present the primary on/off control at the top-left of the form. It remains
   the final state block in the DOM for backwards-compatible saved rule forms. */
.alarm-dialog{position:relative}
.alarm-rule-behavior .alarm-behavior-fields>.alarm-form-state:last-child{position:absolute;z-index:2;top:61px;left:20px;width:260px;min-height:38px;padding:2px 8px;border-color:#d7e3f1;background:#f8fbff}
.alarm-rule-behavior .alarm-behavior-fields>.alarm-form-state:last-child>span:after{display:block;color:#64748b;font-size:10px;font-weight:400;content:"是否参与告警判定"}
.alarm-dialog h3{padding-right:20px}
@media(max-width:900px){.alarm-dialog{width:calc(100vw - 24px)}.alarm-rule-columns{grid-template-columns:1fr;gap:18px}.alarm-rule-behavior{padding:16px 0 0;border-left:0;border-top:1px solid #e5edf7}.alarm-form .wide{grid-column:1/-1}}
@media(max-width:600px){.alarm-dialog-backdrop{padding:12px}.alarm-dialog h3{padding:13px 16px}.alarm-rule-behavior .alarm-behavior-fields>.alarm-form-state:last-child{top:53px;left:16px;width:calc(100% - 32px);min-height:36px}.alarm-rule-behavior .alarm-behavior-fields>.alarm-form-state:last-child>span:after{display:none}.alarm-form{padding:58px 16px 14px}.alarm-rule-basics{grid-template-columns:1fr;gap:10px}.alarm-condition-fields{grid-template-columns:1fr}.alarm-behavior-fields{grid-template-columns:repeat(2,minmax(0,1fr))}.alarm-timing-hysteresis{grid-column:1/-1}.alarm-reminder-controls{align-items:flex-end;flex-direction:column;gap:6px}.alarm-dialog>.dialog-actions{padding:10px 16px}.alarm-rule-behavior .alarm-help-tooltip{left:-28px;width:min(300px,calc(100vw - 76px))}.alarm-limit-head,.alarm-limit-row{grid-template-columns:72px minmax(60px,1fr) 76px;gap:6px}}
</style>
